insert into passages (id, text, difficulty_level, b, active) values
('75f077b5-fdfd-4ae1-bcb7-f9f8bb8373bc', 'Emma works at a small bakery in the center of town. She wakes up very early every morning, usually around four thirty, so that the bread and pastries are ready before the shop opens at seven. On weekdays, the bakery sells mostly to people on their way to work, who stop in for coffee and a croissant. On weekends, however, families come in together and often stay to eat breakfast at the small tables near the window. Emma''s favorite part of the job is decorating birthday cakes, which customers usually order a few days in advance. She says that seeing the customers'' happy faces when they pick up a cake makes the early mornings worth it.', 1, -2.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('c8168c14-e15e-48ee-ad8a-83cccf55d052', 'sentence_completion', 'She ___ her homework before dinner every day.', NULL, '[{"id": "c", "text": "finishes"}, {"id": "b", "text": "finished"}, {"id": "d", "text": "finishing"}, {"id": "a", "text": "finish"}]'::jsonb, 0, '{"strategy": "every day = כל יום. פועל הווה פשוט בגוף שלישי יחיד עם she.", "correct_reason": "finishes = מסיימת. she + פועל בהווה מקבל s.", "options_analysis": ["נכון! she + פועל בהווה עם s", "עבר לא מתאים ל''every day''", "צורת ing לא מתאימה כאן", "חסר s לגוף שלישי יחיד"]}', 0.62, -2.0, 0.25, 1, 'ai', NULL, true),
('848a75c7-eb44-4cc7-8f06-7965b1decfbe', 'sentence_completion', 'There ___ a lot of people at the party last night.', NULL, '[{"id": "a", "text": "was"}, {"id": "d", "text": "were"}, {"id": "b", "text": "is"}, {"id": "c", "text": "are"}]'::jsonb, 1, '{"strategy": "a lot of people...last night = הרבה אנשים...אתמול בלילה. people הוא רבים, ו-last night = עבר.", "correct_reason": "were = היו. people רבים בעבר.", "options_analysis": ["was = יחיד — לא מתאים ל-people שהוא רבים", "נכון! were = צורת עבר של to be לרבים", "הווה — לא מתאים ל''last night''", "הווה לרבים — לא מתאים ל''last night''"]}', 0.56, -2.0, 0.25, 1, 'ai', NULL, true),
('2828ee18-3e8a-43c3-9f19-e32c56c1a607', 'sentence_completion', 'My brother is ___ than me at math.', NULL, '[{"id": "b", "text": "best"}, {"id": "a", "text": "well"}, {"id": "c", "text": "better"}, {"id": "d", "text": "good"}]'::jsonb, 2, '{"strategy": "than me = ממני. יש כאן השוואה בין שני אנשים.", "correct_reason": "better = יותר טוב. השוואה בין שניים משתמשת בהשוואה יחסית (comparative).", "options_analysis": ["best = עילית — משמש להשוואה בין 3+ לא בין שניים", "well = תואר הפועל — לא מתאים כאן", "נכון! better = השוואתי, מתאים ל-than", "good = צורת יסוד — לא מתאימה להשוואה עם than"]}', 0.52, -2.0, 0.25, 1, 'ai', NULL, true),
('f142164c-ebff-46e7-80f4-2531f3ad2cd5', 'sentence_completion', 'We ___ to the beach every summer when I was a child.', NULL, '[{"id": "d", "text": "go"}, {"id": "a", "text": "going"}, {"id": "b", "text": "goes"}, {"id": "c", "text": "went"}]'::jsonb, 3, '{"strategy": "when I was a child = כשהייתי ילד. עבר.", "correct_reason": "went = הלכנו. עבר של go.", "options_analysis": ["הווה — לא מתאים ל''when I was a child''", "צורת ing לבד ללא עזר — לא תקין דקדוקית", "גוף שלישי יחיד — לא מתאים ל-we", "נכון! went = עבר של go, מתאים לזיכרון מהעבר"]}', 0.67, -2.0, 0.25, 1, 'ai', NULL, true),
('da4d07b8-85d9-4095-b838-36529639c219', 'sentence_completion', 'Please ___ the door when you leave.', NULL, '[{"id": "b", "text": "close"}, {"id": "c", "text": "closes"}, {"id": "d", "text": "closing"}, {"id": "a", "text": "closed"}]'::jsonb, 0, '{"strategy": "Please + פועל = ציווי. אחרי please בא הפועל בצורת הבסיס.", "correct_reason": "close = לסגור. ציווי משתמש בצורת הבסיס של הפועל.", "options_analysis": ["נכון! ציווי (imperative) משתמש בצורת הבסיס", "s מיותר בציווי", "ing לבד לא מתאים לציווי", "עבר לא מתאים לבקשה עתידית"]}', 0.7, -2.0, 0.25, 1, 'ai', NULL, true),
('195aebda-3c2a-47da-82b7-1794411d4481', 'sentence_completion', 'The children ___ playing in the garden right now.', NULL, '[{"id": "d", "text": "is"}, {"id": "a", "text": "are"}, {"id": "b", "text": "am"}, {"id": "c", "text": "was"}]'::jsonb, 1, '{"strategy": "right now = ממש עכשיו + children (רבים). הווה מתמשך.", "correct_reason": "are = הם. children הוא רבים, נדרש are בהווה מתמשך.", "options_analysis": ["is = יחיד — לא מתאים ל-children", "נכון! are = מתאים לילדים (רבים) בהווה", "am = מתאים רק ל-I", "was = עבר — לא מתאים ל''right now''"]}', 0.56, -2.0, 0.25, 1, 'ai', NULL, true),
('6b9998e5-7802-40a4-8b44-40e6ab328720', 'sentence_completion', 'I don''t have ___ money to buy that car.', NULL, '[{"id": "a", "text": "little bit"}, {"id": "c", "text": "few"}, {"id": "b", "text": "much"}, {"id": "d", "text": "many"}]'::jsonb, 2, '{"strategy": "money הוא שם עצם לא ספיר (uncountable). money לא נספר.", "correct_reason": "much = הרבה, משמש לשמות עצם לא ספירים.", "options_analysis": ["little bit לא צורה תקנית כאן", "few = משמש לספירים — לא מתאים ל-money", "נכון! much = מתאים לשם עצם לא ספיר כמו money", "many = משמש לשמות עצם ספירים ברבים — money לא נספר"]}', 0.65, -2.0, 0.25, 1, 'ai', NULL, true),
('b85c8833-5e16-4123-9ea7-71c2abb5e6c4', 'sentence_completion', 'He always ___ his teeth before going to bed.', NULL, '[{"id": "c", "text": "brushing"}, {"id": "b", "text": "brush"}, {"id": "a", "text": "brushed"}, {"id": "d", "text": "brushes"}]'::jsonb, 3, '{"strategy": "always = תמיד. הרגל קבוע בהווה, גוף שלישי יחיד he.", "correct_reason": "brushes = מצחצח. he + פועל בהווה מקבל s.", "options_analysis": ["ing לבד ללא עזר לא תקין", "חסר s לגוף שלישי יחיד", "עבר לא מתאים ל-always שמתאר הרגל קבוע", "נכון! he + פועל בהווה עם s, מתאים ל-always"]}', 0.65, -2.0, 0.25, 1, 'ai', NULL, true),
('263260f1-34de-4b92-b52f-6c6a58d08bd7', 'sentence_completion', 'The movie was ___ interesting that we watched it twice.', NULL, '[{"id": "b", "text": "so"}, {"id": "d", "text": "too"}, {"id": "a", "text": "such"}, {"id": "c", "text": "very"}]'::jsonb, 0, '{"strategy": "...that we watched it twice = שראינו אותו פעמיים. תבנית so + adjective + that.", "correct_reason": "so = כל כך. so + תואר + that מבטא תוצאה.", "options_analysis": ["נכון! so + adjective + that = תבנית תוצאה תקנית", "too לא מתחבר עם that באותה תבנית", "such משמש עם שם עצם (such a...) לא עם תואר לבד", "very לא מתחבר עם that בתבנית תוצאה"]}', 0.69, -2.0, 0.25, 1, 'ai', NULL, true),
('8a55c2f2-e200-4dec-8953-6aca0ba7e979', 'sentence_completion', 'Can you tell me where ___ the nearest bank?', NULL, '[{"id": "a", "text": "was"}, {"id": "d", "text": "is"}, {"id": "c", "text": "it is"}, {"id": "b", "text": "it was"}]'::jsonb, 1, '{"strategy": "where...bank = איפה...בנק. שאלה עקיפה (indirect question) על מיקום בהווה.", "correct_reason": "is = נמצא. ''where is the nearest bank'' בתוך שאלה עקיפה.", "options_analysis": ["עבר לא מתאים לשאלה על מיקום נוכחי", "נכון! where + is + subject בשאלה עקיפה על מקום", "סדר מילים שגוי — אין כפילות subject", "עבר וכפילות subject — לא תקין"]}', 0.74, -2.0, 0.25, 1, 'ai', NULL, true),
('32a66ff7-12fd-473b-a8bb-ed765e99067c', 'sentence_completion', 'She has lived in this city ___ five years.', NULL, '[{"id": "b", "text": "since"}, {"id": "c", "text": "from"}, {"id": "a", "text": "for"}, {"id": "d", "text": "during"}]'::jsonb, 2, '{"strategy": "five years = חמש שנים — משך זמן. for משמש עם תקופת זמן, since עם נקודת זמן.", "correct_reason": "for = במשך. for + משך זמן (five years).", "options_analysis": ["since משמש עם נקודת זמן ספציפית (since 2018) לא עם משך", "from משמש לנקודת התחלה, לא למשך", "נכון! for + תקופת זמן (five years)", "during משמש לאירוע ספציפי, לא למשך פשוט"]}', 0.72, -2.0, 0.25, 1, 'ai', NULL, true),
('bb917426-304f-49fa-ab57-336020432b45', 'sentence_completion', 'If it rains tomorrow, we ___ the picnic.', NULL, '[{"id": "a", "text": "canceled"}, {"id": "b", "text": "canceling"}, {"id": "d", "text": "cancel"}, {"id": "c", "text": "will cancel"}]'::jsonb, 3, '{"strategy": "If it rains tomorrow = תנאי סוג ראשון (עתיד אמיתי).", "correct_reason": "will cancel = נבטל. תנאי סוג 1: if + present, will + base verb.", "options_analysis": ["עבר לא מתאים לתנאי עתידי", "ing לבד ללא עזר לא תקין", "חסר will לתנאי סוג ראשון", "נכון! if + present, will + verb = תנאי סוג 1"]}', 0.71, -2.0, 0.25, 1, 'ai', NULL, true),
('7142e6f4-2ef5-4929-bd12-e616469e08f0', 'restatement', 'Tom is taller than his sister.', NULL, '[{"id": "b", "text": "Tom''s sister is shorter than Tom."}, {"id": "c", "text": "Tom and his sister are the same height."}, {"id": "a", "text": "Tom''s sister is taller than Tom."}, {"id": "d", "text": "Tom''s sister is the tallest in the family."}]'::jsonb, 0, '{"strategy": "taller than = יותר גבוה מ-. השוואה בין שניים.", "correct_reason": "אותה משמעות: אם טום גבוה יותר, האחות שלו נמוכה יותר ממנו.", "options_analysis": ["נכון! אותה משמעות: האחות נמוכה יותר מטום", "סותר את ההשוואה — הם לא שווים", "הפוך — סותר ''Tom is taller''", "לא נאמר במקור — אין מידע על שאר המשפחה"]}', 0.66, -2.0, 0.25, 1, 'ai', NULL, true),
('ec35407d-3f43-4ce0-82d8-f79adab4d07c', 'restatement', 'I usually go to school by bus.', NULL, '[{"id": "a", "text": "I have never been to school."}, {"id": "d", "text": "I go to school by bus most of the time."}, {"id": "b", "text": "I always walk to school."}, {"id": "c", "text": "I never go to school by bus."}]'::jsonb, 1, '{"strategy": "usually = בדרך כלל. תדירות גבוהה אך לא תמיד.", "correct_reason": "אותה משמעות: usually = ברוב הזמן.", "options_analysis": ["סותר את קיום בית הספר עצמו", "נכון! usually = ברוב הזמן, אותה משמעות בדיוק", "הפוך — סותר ''by bus''", "הפוך — סותר ''usually''"]}', 0.81, -2.0, 0.25, 1, 'ai', NULL, true),
('0017aa78-9c4f-4063-bc3c-b81069fab639', 'restatement', 'The store closes at 9 PM on weekdays.', NULL, '[{"id": "c", "text": "The store is open 24 hours on weekdays."}, {"id": "b", "text": "The store is closed all day on weekdays."}, {"id": "d", "text": "On weekdays, the store shuts its doors at 9 PM."}, {"id": "a", "text": "The store never closes."}]'::jsonb, 2, '{"strategy": "closes at 9 PM = נסגר ב-9 בערב. פרט זמן.", "correct_reason": "אותה משמעות בדיוק: נסגר בשעה 9 בערב בימי חול.", "options_analysis": ["סותר ''closes at 9 PM''", "הפוך — סותר ''closes at 9 PM'' (נסגר בערב, לא סגור כל היום)", "נכון! אותה משמעות בדיוק: נסגר בשעה 9 בערב", "הפוך — סותר את קיום שעת הסגירה"]}', 0.84, -2.0, 0.25, 1, 'ai', NULL, true),
('8676ea42-1750-4697-8660-0d843d424144', 'restatement', 'My father works as a doctor at the hospital.', NULL, '[{"id": "b", "text": "My father used to be a doctor."}, {"id": "d", "text": "My father is a patient at the hospital."}, {"id": "a", "text": "My father does not work at all."}, {"id": "c", "text": "My father is a doctor who works at the hospital."}]'::jsonb, 3, '{"strategy": "works as a doctor = עובד כרופא. תיאור מקצוע.", "correct_reason": "אותה משמעות בדיוק: אבי הוא רופא שעובד בבית החולים.", "options_analysis": ["סותר את הזמן ההווה — ''works'' מתאר הווה, לא עבר", "סותר ''works as a doctor'' — הוא לא מטופל אלא עובד", "סותר את ''works'' — הוא כן עובד", "נכון! אותה משמעות בדיוק"]}', 0.56, -2.0, 0.25, 1, 'ai', NULL, true),
('96111e4b-2dd4-4176-8d3f-c915c9a6671c', 'restatement', 'It is raining heavily outside right now.', NULL, '[{"id": "a", "text": "There is a lot of rain falling outside at this moment."}, {"id": "d", "text": "It never rains in this area."}, {"id": "c", "text": "It rained yesterday but not today."}, {"id": "b", "text": "The weather is sunny right now."}]'::jsonb, 0, '{"strategy": "raining heavily...right now = יורד גשם חזק...עכשיו.", "correct_reason": "אותה משמעות בדיוק: הרבה גשם יורד כרגע בחוץ.", "options_analysis": ["נכון! אותה משמעות בדיוק: יורד הרבה גשם כרגע", "סותר את קיום הגשם המתואר", "סותר ''right now'' — זה קורה עכשיו, לא אתמול", "הפוך — ''sunny'' סותר ''raining''"]}', 0.74, -2.0, 0.25, 1, 'ai', NULL, true),
('210750af-e5e4-4c7c-9039-1a8497290934', 'restatement', 'She can speak three languages fluently.', NULL, '[{"id": "c", "text": "She cannot speak any language."}, {"id": "b", "text": "She is able to speak three languages very well."}, {"id": "a", "text": "She can only speak one language."}, {"id": "d", "text": "She is learning to speak her first language."}]'::jsonb, 1, '{"strategy": "can speak...fluently = יכולה לדבר...בשטף. יכולת ברמה גבוהה.", "correct_reason": "אותה משמעות בדיוק: מסוגלת לדבר שלוש שפות היטב.", "options_analysis": ["הפוך גמור — סותר ''can speak''", "נכון! אותה משמעות בדיוק: מסוגלת לדבר שלוש שפות היטב", "סותר ''three languages''", "סותר ''fluently'' — היא כבר שולטת, לא לומדת שפה ראשונה"]}', 0.53, -2.0, 0.25, 1, 'ai', NULL, true),
('83433148-aa7d-468b-af0d-84ee54f75da4', 'restatement', 'The museum is free for children under twelve.', NULL, '[{"id": "b", "text": "The museum is closed to children."}, {"id": "c", "text": "Only adults over twelve can enter the museum."}, {"id": "d", "text": "Children who are younger than twelve do not have to pay to enter the museum."}, {"id": "a", "text": "All visitors must pay to enter the museum."}]'::jsonb, 2, '{"strategy": "free for children under twelve = חינם לילדים מתחת לגיל 12.", "correct_reason": "אותה משמעות בדיוק: ילדים מתחת לגיל 12 לא משלמים.", "options_analysis": ["הפוך — סותר ''free for children'' (הם כן יכולים להיכנס)", "הפוך ומעוות — ''under twelve'' פירושו מתחת לגיל 12, לא מעליו", "נכון! אותה משמעות בדיוק: ילדים מתחת לגיל 12 לא משלמים", "הפוך — סותר ''free for children under twelve''"]}', 0.7, -2.0, 0.25, 1, 'ai', NULL, true),
('7ef0bc76-183b-4726-a00b-fe1ba787c975', 'restatement', 'We need to buy some milk and eggs from the store.', NULL, '[{"id": "a", "text": "We already bought milk and eggs."}, {"id": "b", "text": "We don''t need anything from the store."}, {"id": "d", "text": "We need to sell milk and eggs."}, {"id": "c", "text": "We have to purchase milk and eggs at the store."}]'::jsonb, 3, '{"strategy": "need to buy = צריכים לקנות. משמעות זהה.", "correct_reason": "אותה משמעות בדיוק: חייבים לרכוש חלב וביצים בחנות.", "options_analysis": ["סותר ''need to buy'' — עדיין לא קנו", "סותר את קיום הצורך שתואר", "הפוך — ''sell'' סותר ''buy''", "נכון! אותה משמעות בדיוק: חייבים לרכוש חלב וביצים"]}', 0.57, -2.0, 0.25, 1, 'ai', NULL, true),
('6a5dae34-d6e5-4f3e-9e90-38b3f2bf7929', 'restatement', 'The train arrives at the station every hour.', NULL, '[{"id": "a", "text": "A train comes to the station once every sixty minutes."}, {"id": "c", "text": "The train arrives only once a day."}, {"id": "b", "text": "The station has no trains at all."}, {"id": "d", "text": "The train never arrives at the station."}]'::jsonb, 0, '{"strategy": "every hour = כל שעה. תדירות קבועה.", "correct_reason": "אותה משמעות בדיוק: רכבת מגיעה כל שישים דקות.", "options_analysis": ["נכון! אותה משמעות בדיוק: כל שישים דקות = כל שעה", "סותר ''every hour'' — זה קורה הרבה יותר מפעם ביום", "סותר את קיום הרכבות בתחנה", "הפוך — סותר ''arrives...every hour''"]}', 0.57, -2.0, 0.25, 1, 'ai', NULL, true),
('ade155f2-7be6-4341-ac0e-8a68fe79bbcd', 'restatement', 'My sister is younger than me by two years.', NULL, '[{"id": "c", "text": "My sister and I are twins."}, {"id": "a", "text": "My sister was born two years after me."}, {"id": "d", "text": "I am younger than my sister."}, {"id": "b", "text": "My sister is two years older than me."}]'::jsonb, 1, '{"strategy": "younger...by two years = צעירה יותר בשנתיים.", "correct_reason": "אותה משמעות בדיוק: האחות נולדה שנתיים אחריי.", "options_analysis": ["סותר ''by two years'' — יש הבדל גילאים", "נכון! אותה משמעות בדיוק: אם היא צעירה יותר, היא נולדה אחריי", "הפוך — סותר ''younger than me''", "הפוך — ''older'' סותר ''younger''"]}', 0.83, -2.0, 0.25, 1, 'ai', NULL, true),
('4d71a114-bb47-4e6e-9707-eb3f48292d4f', 'restatement', 'He forgot to bring his umbrella even though it was raining.', NULL, '[{"id": "b", "text": "He remembered to bring his umbrella in the rain."}, {"id": "a", "text": "It was not raining at all that day."}, {"id": "d", "text": "Despite the rain, he did not remember to take his umbrella with him."}, {"id": "c", "text": "He never owns an umbrella."}]'::jsonb, 2, '{"strategy": "forgot to bring...even though raining = שכח להביא...למרות שירד גשם. ניגוד.", "correct_reason": "אותה משמעות בדיוק: למרות הגשם, הוא לא זכר לקחת מטרייה.", "options_analysis": ["הפוך — סותר ''forgot to bring''", "סותר ''even though it was raining''", "נכון! אותה משמעות בדיוק: למרות הגשם, הוא לא זכר לקחת מטרייה", "לא נאמר במקור — אין מידע על בעלות כללית על מטרייה"]}', 0.62, -2.0, 0.25, 1, 'ai', NULL, true),
('8ace220c-7260-4c03-aeb2-6bb0da964225', 'reading_comprehension', 'What time does Emma usually wake up?', '75f077b5-fdfd-4ae1-bcb7-f9f8bb8373bc', '[{"id": "c", "text": "She does not wake up early"}, {"id": "b", "text": "Around nine"}, {"id": "d", "text": "Around seven"}, {"id": "a", "text": "Around four thirty"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את השעה בפסקה.", "correct_reason": "הפסקה אומרת: ''she wakes up very early every morning, usually around four thirty''.", "options_analysis": ["סותר את הפסקה שאומרת שהיא מתעוררת מוקדם", "לא נאמר בפסקה", "זו שעת פתיחת החנות, לא שעת ההשכמה", "נכון! נאמר במפורש בפסקה"]}', 0.63, -2.0, 0.25, 1, 'ai', NULL, true),
('c5c9a16b-b19e-489c-97a5-ab1f17d83c27', 'reading_comprehension', 'According to the passage, who mostly visits the bakery on weekdays?', '75f077b5-fdfd-4ae1-bcb7-f9f8bb8373bc', '[{"id": "c", "text": "People on their way to work"}, {"id": "a", "text": "Tourists visiting the town"}, {"id": "b", "text": "No one visits on weekdays"}, {"id": "d", "text": "Families with children"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש מי מבקר בימי חול.", "correct_reason": "הפסקה אומרת: ''On weekdays, the bakery sells mostly to people on their way to work''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא מוזכר בפסקה כלל", "סותר את הפסקה שמתארת מכירות בימי חול", "זה מתואר עבור סופי שבוע, לא ימי חול"]}', 0.78, -2.0, 0.25, 1, 'ai', NULL, true),
('425e1f64-9205-464b-a64d-c50d8b59f0dd', 'reading_comprehension', 'What is Emma''s favorite part of her job?', '75f077b5-fdfd-4ae1-bcb7-f9f8bb8373bc', '[{"id": "d", "text": "Cleaning the bakery"}, {"id": "c", "text": "Decorating birthday cakes"}, {"id": "b", "text": "Waking up early"}, {"id": "a", "text": "Selling coffee to workers"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את מה שאמה הכי אוהבת.", "correct_reason": "הפסקה אומרת: ''Emma''s favorite part of the job is decorating birthday cakes''.", "options_analysis": ["לא מוזכר בפסקה כלל", "נכון! נאמר במפורש בפסקה", "הפוך — זו לא החלק האהוב, אלא חלק קשה מהעבודה", "לא מוזכר כחלק האהוב בפסקה"]}', 0.52, -2.0, 0.25, 1, 'ai', NULL, true),
('957e8071-0c22-41d2-bb8a-104bff7913b5', 'reading_comprehension', 'When does the bakery open, according to the passage?', '75f077b5-fdfd-4ae1-bcb7-f9f8bb8373bc', '[{"id": "b", "text": "It never opens"}, {"id": "c", "text": "At nine"}, {"id": "a", "text": "At seven"}, {"id": "d", "text": "At four thirty"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש את שעת הפתיחה.", "correct_reason": "הפסקה אומרת: ''the shop opens at seven''.", "options_analysis": ["סותר את הפסקה שמתארת פתיחה בשעה מסוימת", "לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "זו שעת ההשכמה של אמה, לא שעת הפתיחה"]}', 0.52, -2.0, 0.25, 1, 'ai', NULL, true);